export default (got) => {
    return {
        async list() {
            const devices = await got.get(`devices`).json();
            return devices.filter((d) => d.deviceType === 'lightSensor');
        },
        async get({ id }) {
            const device = await got.get(`devices/${id}`).json();
            if (device.deviceType !== 'lightSensor') {
                throw new Error('The requested device is not a lightSensor');
            }
            return device;
        },
    };
};
